def score(c,s):
 H,S,T=c.split("\n")
 E=list(S)
 for i,q in enumerate(S):
  if q=="x"and H[i]=="_":
   j=i;E[i]="-"
   while H[j]=="_":
    j+=1+(S[j+1]=="|");E[j]="-"
   E[j]="x"
 f=lambda z:re.sub("[^x._-]","",z).replace("_",".")
 R=[y for y in map(f,s.split("\n"))if len(y)>3]
 return int(R==[f(H),f("".join(E))])
